<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
$id=(int)($_GET['event_id']??0);$events=all('SELECT id,name FROM events ORDER BY starts_at DESC');$a=$id?[$id]:[];
$rows=all("SELECT e.id,e.name,e.type,e.starts_at,(SELECT COUNT(*) FROM registrations r WHERE r.event_id=e.id AND r.status='Pagado') paid,(SELECT COALESCE(SUM(monto_cobrado),0) FROM registrations r WHERE r.event_id=e.id) income,(SELECT COALESCE(SUM(stock*unit_cost),0) FROM materials m WHERE m.event_id=e.id) materials,(SELECT COALESCE(SUM(amount),0) FROM expenses g WHERE g.event_id=e.id) expenses FROM events e".($id?' WHERE e.id=?':'').' ORDER BY e.starts_at DESC',$a);
$heads=['Evento','Tipo','Fecha','Inscripciones confirmadas','Ingresos Bs','Materiales Bs','Otros gastos Bs','Gasto total Bs','Saldo Bs'];
if(($_GET['export']??'')==='csv'){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="finanzas_unior.csv"');$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,$heads,';');foreach($rows as $r){$cost=(float)$r['materials']+(float)$r['expenses'];$v=[$r['name'],$r['type'],$r['starts_at'],$r['paid'],$r['income'],$r['materials'],$r['expenses'],number_format($cost,2,'.',''),number_format($r['income']-$cost,2,'.','')];$v=array_map(fn($x)=>preg_match('/^[\s]*[=+@-]/u',(string)$x)?"'".$x:$x,$v);fputcsv($out,$v,';');}exit;}
headerPage('Cuánto se generó y cuánto se gastó por evento'); ?>
<div class="card p-4 no-print"><form method="get"><input type="hidden" name="p" value="finance"><?php selectField('event_id','Curso / congreso / taller',[0=>'Todos']+array_column($events,'name','id'),(string)$id);?><button class="btn btn-primary">Generar reporte financiero</button> <button name="export" value="csv" class="btn btn-success">Exportar Excel (CSV)</button> <button type="button" class="btn btn-outline-primary" onclick="print()">Imprimir / PDF</button></form></div>
<div class="card p-4"><h3>UNIOR · Reporte financiero por evento</h3><p>Generado: <?=e(date('d/m/Y H:i'))?> · Ingresos de pagos confirmados y gastos acumulados.</p><div class="table-responsive"><table class="table table-bordered"><tr><?php foreach($heads as $h)echo '<th>'.e($h).'</th>';?></tr><?php $income=0;$costs=0;foreach($rows as $r):$cost=(float)$r['materials']+(float)$r['expenses'];$income+=(float)$r['income'];$costs+=$cost;?><tr><td><?=e($r['name'])?></td><td><?=e($r['type'])?></td><td><?=e($r['starts_at'])?></td><td><?=e($r['paid'])?></td><td><?=money($r['income'])?></td><td><?=money($r['materials'])?></td><td><?=money($r['expenses'])?></td><td><?=money($cost)?></td><td><?=money($r['income']-$cost)?></td></tr><?php endforeach?></table></div><p><b>Total generado: <?=money($income)?> · Total gastado: <?=money($costs)?> · Saldo: <?=money($income-$costs)?></b></p><p>Compras de materiales = stock total × costo unitario. Otros gastos se registran por separado para evitar duplicar compras.</p></div>
<?php if($id):?><div class="row"><div class="col-lg-6"><div class="card p-4"><h3>Detalle de costos de materiales</h3><table class="table"><tr><th>Material</th><th>Comprado</th><th>Unitario</th><th>Total</th></tr><?php foreach(all('SELECT * FROM materials WHERE event_id=?',[$id]) as $m)echo '<tr><td>'.e($m['name']).'</td><td>'.e($m['stock']).'</td><td>'.money($m['unit_cost']).'</td><td>'.money($m['stock']*$m['unit_cost']).'</td></tr>';?></table></div></div><div class="col-lg-6"><div class="card p-4"><h3>Detalle de otros gastos</h3><p><a href="<?=url('p=expense_report&event_id='.$id)?>">Ver totales por categoría</a></p><table class="table"><tr><th>Fecha</th><th>Categoría</th><th>Detalle</th><th>Monto</th></tr><?php foreach(all('SELECT g.*,COALESCE(c.name,\'Sin categoría\') category_name FROM expenses g LEFT JOIN expense_categories c ON c.id=g.category_id WHERE g.event_id=? ORDER BY g.spent_on',[$id]) as $g)echo '<tr><td>'.e($g['spent_on']).'</td><td>'.e($g['category_name']).'</td><td>'.e($g['description']).'</td><td>'.money($g['amount']).'</td></tr>';?></table></div></div></div><?php endif;footerPage();
